use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<i32> = Vec::new();

    // Copy a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a@.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i += 1;
    }

    // Copy b (appending after all of a)
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b@.len(),
            res@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            forall|t: int| 0 <= t < j as int ==> res@[a@.len() + t] == b@[t],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!

